describe('Form Data Persistence', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should retain form data when navigating away and returning', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="email"]').type('testuser@example.com');
        cy.get('input[name="password"]').type('password123');

        // Simulate navigating away
        cy.visit('/another-page'); // Replace with the actual URL of another page

        // Navigate back to the form page
        cy.visit('/form-page');

        // Assert that the form data is still present
        cy.get('input[name="username"]').should('have.value', 'testuser');
        cy.get('input[name="email"]').should('have.value', 'testuser@example.com');
        cy.get('input[name="password"]').should('have.value', 'password123');
    });

    it('should not retain form data if the form is reset', () => {
        cy.get('input[name="username"]').type('testuser');
        cy.get('input[name="email"]').type('testuser@example.com');
        cy.get('input[name="password"]').type('password123');

        // Simulate resetting the form
        cy.get('button[type="reset"]').click(); // Assuming there is a reset button

        // Assert that the form fields are empty
        cy.get('input[name="username"]').should('have.value', '');
        cy.get('input[name="email"]').should('have.value', '');
        cy.get('input[name="password"]').should('have.value', '');
    });
});
